import * as THREE from 'three/webgpu';
import { uv, mix, color, vec3, hash } from 'three/tsl';
import gsap from 'gsap';
import { createMSDFText } from '@/text';

function resolveText(config, role, fallback) {
  const list = Array.isArray(config?.textContent) ? config.textContent : [];
  const found = list.find(
    (entry) => entry && typeof entry === 'object' && String(entry.role || '').toLowerCase() === role
  );
  return found && typeof found.text === 'string' ? found.text : fallback;
}

function collectMaterials(root) {
  const mats = [];
  root.traverse((obj) => {
    if (obj.material) {
      if (Array.isArray(obj.material)) mats.push(...obj.material);
      else mats.push(obj.material);
    }
  });
  return mats;
}

function buildText(ctx, str, opts) {
  const obj = createMSDFText({
    text: str,
    atlas: ctx.fontAtlas,
    font: opts.font,
    weight: opts.weight,
    fontSize: opts.size,
    letterSpacing: opts.letterSpacing || 0,
    lineHeight: opts.lineHeight || 1.1,
    color: opts.color,
    anchor: opts.anchor || 'center',
  });
  obj.updateMatrixWorld(true);
  return obj;
}

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'nova-atelier-kinetic-headline';
  group.userData.handlers = {};

  const visualColors = config?.visual?.colors || {};
  const palette = {
    background: visualColors.background || '#0b0b10',
    accent: visualColors.accent || '#ff2a38',
    paper: visualColors.paper || '#e8ecf2',
  };
  const gradientStops =
    Array.isArray(visualColors.gradientStops) && visualColors.gradientStops.length >= 2
      ? visualColors.gradientStops
      : [
          { at: 0, hex: '#0b0b10' },
          { at: 1, hex: '#13131a' },
        ];
  const gradientStart = gradientStops[0].hex;
  const gradientEnd = gradientStops[gradientStops.length - 1].hex;

  const typography = config?.typography || {};
  const heroType = typography.hero || {};
  const subheadType = typography.subhead || {};
  const captionType = typography.caption || {};

  const tweens = [];
  const primitiveControllers = [];

  // ---------------------------------------------------------------------
  // Backdrop: 7x5.5 engineered gradient plane + 1.5% mono grain (TSL only)
  // ---------------------------------------------------------------------
  const backdropGeo = new THREE.PlaneGeometry(7, 5.5);
  const backdropMat = new THREE.MeshBasicNodeMaterial();
  const gradientNode = mix(color(gradientStart), color(gradientEnd), uv().y);
  const grainNode = hash(uv().mul(1536.0)).sub(0.5).mul(0.015);
  backdropMat.colorNode = gradientNode.add(vec3(grainNode, grainNode, grainNode));
  backdropMat.toneMapped = false;
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -1.5);
  backdrop.renderOrder = -1;
  group.add(backdrop);

  // ---------------------------------------------------------------------
  // Caption kicker
  // ---------------------------------------------------------------------
  const captionStr = resolveText(config, 'caption', 'NOVA ATELIER / CALIBRE PROGRAM');
  const captionText = buildText(ctx, captionStr, {
    font: captionType.family || 'JetBrains Mono',
    weight: captionType.fontWeight || 700,
    size: 0.09,
    color: palette.paper,
    letterSpacing: captionType.letterSpacing ?? 0.12,
    anchor: 'center',
  });
  const captionBaseY = 1.15;
  captionText.position.set(0, captionBaseY, 0);
  group.add(captionText);

  // ---------------------------------------------------------------------
  // Hero kinetic type — per-word groups, front-to-back z parallax
  // ---------------------------------------------------------------------
  const heroStr = resolveText(config, 'hero', 'TIME, MACHINED.');
  const heroGroup = new THREE.Group();
  heroGroup.name = 'hero-line';
  const words = heroStr.split(' ').filter(Boolean);
  const zOffsets = [0.12, 0.0, -0.12];
  const wordGap = 0.16;
  const heroBaseY = 0.4;

  const wordEntries = words.map((w, i) => {
    const wordText = buildText(ctx, w, {
      font: heroType.family || 'Lora',
      weight: heroType.fontWeight || 600,
      size: 0.62,
      color: palette.paper,
      letterSpacing: heroType.letterSpacing ?? -0.01,
      anchor: 'left',
    });
    const box = new THREE.Box3().setFromObject(wordText);
    const measured = box.max.x - box.min.x;
    const width = Number.isFinite(measured) && measured > 0 ? measured : w.length * 0.62 * 0.6;
    return { obj: wordText, width, z: zOffsets[i % zOffsets.length] };
  });

  const totalWidth =
    wordEntries.reduce((sum, w) => sum + w.width, 0) + wordGap * Math.max(0, wordEntries.length - 1);
  let cursorX = -totalWidth / 2;
  wordEntries.forEach((entry) => {
    entry.obj.position.set(cursorX, heroBaseY, entry.z);
    heroGroup.add(entry.obj);
    cursorX += entry.width + wordGap;
  });
  group.add(heroGroup);

  // ---------------------------------------------------------------------
  // Accent underline rule — machined signal-red emissive plane
  // ---------------------------------------------------------------------
  const underlineGeo = new THREE.PlaneGeometry(2.6, 0.045);
  underlineGeo.translate(1.3, 0, 0); // pivot at left edge for scaleX anchor-left
  const underlineMat = new THREE.MeshStandardNodeMaterial();
  underlineMat.colorNode = color(palette.accent);
  underlineMat.emissiveNode = color(palette.accent).mul(1.2);
  underlineMat.roughness = 0.5;
  underlineMat.metalness = 0.4;
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(-1.3, -0.05, 0.02);
  underline.scale.x = 0.0001;
  group.add(underline);

  // ---------------------------------------------------------------------
  // Subhead
  // ---------------------------------------------------------------------
  const subheadStr = resolveText(config, 'subhead', 'Every calibre begins as a solid billet.');
  const subheadGroup = buildText(ctx, subheadStr, {
    font: subheadType.family || 'Lora',
    weight: subheadType.fontWeight || 400,
    size: 0.2,
    color: palette.paper,
    letterSpacing: subheadType.letterSpacing ?? 0.02,
    anchor: 'center',
  });
  const subheadBaseY = -0.65;
  subheadGroup.position.set(0, subheadBaseY, 0);
  group.add(subheadGroup);

  // ---------------------------------------------------------------------
  // Scene placement
  // ---------------------------------------------------------------------
  const sp = config?.scenePosition || {};
  group.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);
  if (sp.rotationXYZ) {
    group.rotation.set(sp.rotationXYZ.x ?? 0, sp.rotationXYZ.y ?? 0, sp.rotationXYZ.z ?? 0);
  }
  if (sp.scaleXYZ) {
    group.scale.set(sp.scaleXYZ.x ?? 1, sp.scaleXYZ.y ?? 1, sp.scaleXYZ.z ?? 1);
  }

  // ---------------------------------------------------------------------
  // Initial hidden states (pre-animation)
  // ---------------------------------------------------------------------
  const captionMats = collectMaterials(captionText);
  captionMats.forEach((m) => {
    m.transparent = true;
    m.opacity = 0;
  });
  captionText.position.y = captionBaseY + 0.2;

  const subheadMats = collectMaterials(subheadGroup);
  subheadMats.forEach((m) => {
    m.transparent = true;
    m.opacity = 0;
  });
  subheadGroup.position.y = subheadBaseY + 0.2;

  heroGroup.scale.set(1.04, 1.04, 1.04);

  // ---------------------------------------------------------------------
  // Apply EVERY configured cinematic primitive (never inline the logic)
  // ---------------------------------------------------------------------
  const primitiveList = Array.isArray(config?.cinematicPrimitives) ? config.cinematicPrimitives : [];
  let kineticParams = { staggerMs: 60, riseUnits: 0.35 };

  primitiveList.forEach((p) => {
    const fn = ctx?.primitives?.[p.name];
    if (typeof fn !== 'function') return;
    const target = p.name === 'kinetic-text' ? heroGroup : group;
    const params = p.params || {};
    if (p.name === 'kinetic-text') kineticParams = { ...kineticParams, ...params };
    const controller = fn(target, params);
    if (controller) primitiveControllers.push(controller);
  });

  // ---------------------------------------------------------------------
  // Timing derived from the kinetic-text stagger so downstream reveals
  // (weighted-settle, underline, subhead) land after the glyphs do.
  // ---------------------------------------------------------------------
  const glyphCount = Math.max(1, heroStr.replace(/\s+/g, '').length);
  const staggerSec = kineticParams.staggerMs / 1000;
  const riseSec = 0.7;
  const lastGlyphLand = (glyphCount - 1) * staggerSec + riseSec;

  // caption fade-up
  const captionTween = gsap.timeline();
  captionTween.to(captionMats, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  captionTween.to(captionText.position, { y: captionBaseY, duration: 0.5, ease: 'power2.out' }, 0);
  tweens.push(captionTween);

  // weighted-settle: overshoot 1.04 -> 1.0 once the glyphs land
  const settleTween = gsap.to(heroGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
    delay: lastGlyphLand,
  });
  tweens.push(settleTween);

  // accent underline reveal, 120ms after the last glyph lands
  const underlineTween = gsap.to(underline.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.out',
    delay: lastGlyphLand + 0.12,
  });
  tweens.push(underlineTween);

  // subhead fade-up, aligned with the underline reveal
  const subheadTimeline = gsap.timeline({ delay: lastGlyphLand + 0.12 });
  subheadTimeline.to(subheadMats, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  subheadTimeline.to(subheadGroup.position, { y: subheadBaseY, duration: 0.5, ease: 'power2.out' }, 0);
  tweens.push(subheadTimeline);

  // ---------------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------------
  group.userData.cleanup = () => {
    tweens.forEach((t) => t.kill());
    primitiveControllers.forEach((controller) => {
      if (!controller) return;
      if (typeof controller.kill === 'function') controller.kill();
      else if (typeof controller.dispose === 'function') controller.dispose();
      else if (typeof controller.stop === 'function') controller.stop();
    });
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose?.());
        else obj.material.dispose?.();
      }
    });
  };

  return group;
}
